(() => {
  'use strict';
  const $=id=>document.getElementById(id), defaults={lights:true,animations:true,grid:false,ambient:.28,intensity:1};
  let active=false, editor=null, route='home', fromGame=false, busy=false;
  let controls={sensitivity:1,inertia:true};
  try{const saved=JSON.parse(localStorage.getItem('beyond-menu-controls'));if(saved){controls.sensitivity=Math.max(.5,Math.min(1.5,Number(saved.sensitivity)||1));controls.inertia=saved.inertia!==false;}}catch{}
  function saveControls(){localStorage.setItem('beyond-menu-controls',JSON.stringify(controls));}
  const icon=path=>'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true">'+path+'</svg>';
  const icons={play:icon('<path d="m9 5 10 7-10 7Z"/>'),new:icon('<path d="M12 4v16M4 12h16"/>'),hero:icon('<circle cx="12" cy="7" r="3"/><path d="M5 21v-3a7 7 0 0 1 14 0v3"/>'),world:icon('<path d="m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2Z M9 3v16M15 5v16"/>'),settings:icon('<circle cx="12" cy="12" r="3"/><path d="m9 3-1 3-3 1-2 3 2 2-1 4 3 1 2 4 3-1 3 1 2-4 3-1-1-4 2-2-2-3-3-1-1-3Z"/>'),back:icon('<path d="m14 5-7 7 7 7"/>')};
  function button(label,fn,name,primary=false){const b=document.createElement('button');b.type='button';b.className='cinema-button'+(primary?' primary':'');b.innerHTML=(icons[name]||'')+'<span></span>';b.querySelector('span').textContent=label;b.onclick=async()=>{if(busy)return;busy=true;b.setAttribute('aria-busy','true');try{await fn();}catch(e){$('cinema-status').textContent=e.message;}finally{busy=false;b.removeAttribute('aria-busy');}};return b;}
  function applyPreferences(world=false){if(world&&localStorage.getItem('beyond-menu-preferences-explicit')!=='true'){document.body.classList.toggle('no-animations',!gameDebug.state.settings.animations);return;}try{const pref=JSON.parse(localStorage.getItem('beyond-menu-preferences'));if(pref)Object.assign(gameDebug.state.settings,pref);}catch{}document.body.classList.toggle('no-animations',!gameDebug.state.settings.animations);}
  function persist(explicit=true){if(explicit)localStorage.setItem('beyond-menu-preferences-explicit','true');localStorage.setItem('beyond-menu-preferences',JSON.stringify(gameDebug.state.settings));document.body.classList.toggle('no-animations',!gameDebug.state.settings.animations);}
  function setRoute(name){route=name;document.body.dataset.cinemaRoute=name;editor=null;const el=$('cinematic-menu');el.classList.remove('arrive');void el.offsetWidth;el.classList.add('arrive');el.hidden=name==='heroes'||name==='worlds';}
  function open(){active=true;fromGame=false;document.body.classList.add('cinematic-active');setRoute('home');home();requestAnimationFrame(()=>window.voxel?.resize());}
  function home(){setRoute('home');const root=$('cinematic-menu');root.replaceChildren();const mast=document.createElement('div');mast.className='cinema-mast';mast.innerHTML='<h1>За гранью</h1><div class="cinema-ornament" aria-hidden="true"><i></i></div>';const actions=document.createElement('nav');actions.className='cinema-actions';actions.setAttribute('aria-label','Главное меню');
    const cont=button('Продолжить',()=>Worlds.resume(),'play',true);cont.disabled=!Worlds.current&&!localStorage.getItem(Worlds.resumeKey||'last-world-id');
    actions.append(cont,button('Новая игра',()=>{setRoute('heroes');Heroes.start(false);Heroes.open();},'new',cont.disabled),button('Герои',()=>{setRoute('heroes');return Heroes.list();},'hero'),button('Миры',()=>worlds(),'world'),button('Настройки',settings,'settings'));
    const status=document.createElement('p');status.id='cinema-status';status.setAttribute('role','status');root.append(mast,actions,status);
  }
  async function worlds(){setRoute('worlds');await Heroes.list();$('heroes-title').textContent='Миры';const p=document.createElement('p');p.className='world-selection-note';p.textContent='Выбери героя, чтобы продолжить его мир или начать новый.';$('heroes-body').prepend(p);}
  function closeScreen(){if(fromGame){play();return;}document.querySelectorAll('dialog[open]').forEach(d=>d.close());home();}
  function play(){active=false;editor=null;fromGame=false;document.body.classList.remove('cinematic-active');$('cinematic-menu').hidden=true;applyPreferences(true);requestAnimationFrame(()=>window.voxel?.resize());}
  function settings(category='display'){setRoute('settings');const root=$('cinematic-menu');root.replaceChildren();const head=document.createElement('div');head.className='cinema-head';const back=button('Назад',closeScreen,'back');head.append(back);const h=document.createElement('h2');h.textContent='Настройки';head.append(h);root.append(head);
    const tabs=document.createElement('div');tabs.className='settings-tabs';tabs.setAttribute('role','tablist');
    for(const [id,label]of [['display','Отображение'],['controls','Управление']]){const b=document.createElement('button');b.textContent=label;b.type='button';b.setAttribute('role','tab');b.setAttribute('aria-selected',String(category===id));b.onclick=()=>settings(id);tabs.append(b);}root.append(tabs);
    const panel=document.createElement('section');panel.className='cinema-settings';panel.innerHTML='<h3>Отображение</h3>';const s=gameDebug.state.settings;
    for(const [key,label,action] of [['lights','Освещение','light'],['animations','Анимации','animations'],['grid','Показывать сетку','grid']]){const row=document.createElement('div');row.className='setting-row';const text=document.createElement('span');text.textContent=label;const b=document.createElement('button');b.className='cinema-switch';b.setAttribute('role','switch');b.setAttribute('aria-label',label);b.setAttribute('aria-checked',String(s[key]));b.innerHTML='<i></i>';b.onclick=()=>{s[key]=!s[key];gameDebug.save();gameDebug.render();persist();b.setAttribute('aria-checked',String(s[key]));};row.append(text,b);panel.append(row);}
    for(const [key,label,min,max,step] of [['ambient','Общий свет',.05,.8,.01],['intensity','Яркость факелов',.3,1.5,.01]]){const row=document.createElement('label');row.className='cinema-slider';const text=document.createElement('span');text.textContent=label;const output=document.createElement('output');output.textContent=Math.round(s[key]*100)+'%';const input=document.createElement('input');input.type='range';input.min=min;input.max=max;input.step=step;input.value=s[key];input.setAttribute('aria-label',label);input.oninput=()=>{s[key]=Number(input.value);gameDebug.save();gameDebug.render();persist();output.textContent=Math.round(s[key]*100)+'%';input.style.setProperty('--range',((input.value-min)/(max-min)*100)+'%');};input.style.setProperty('--range',((s[key]-min)/(max-min)*100)+'%');row.append(text,output,input);panel.append(row);}
    if(category==='controls'){
      panel.replaceChildren();const row=document.createElement('div');row.className='setting-row';const label=document.createElement('span');label.textContent='Инерция вращения';const b=document.createElement('button');b.className='cinema-switch';b.setAttribute('role','switch');b.setAttribute('aria-label','Инерция вращения');b.setAttribute('aria-checked',String(controls.inertia));b.innerHTML='<i></i>';b.onclick=()=>{controls.inertia=!controls.inertia;saveControls();b.setAttribute('aria-checked',String(controls.inertia));};row.append(label,b);panel.append(row);
      const slider=document.createElement('label');slider.className='cinema-slider';const text=document.createElement('span');text.textContent='Скорость поворота героя';const output=document.createElement('output');output.textContent=Math.round(controls.sensitivity*100)+'%';const input=document.createElement('input');input.type='range';input.min='.5';input.max='1.5';input.step='.05';input.value=controls.sensitivity;input.setAttribute('aria-label','Скорость поворота героя');input.style.setProperty('--range',(controls.sensitivity-.5)*100+'%');input.oninput=()=>{controls.sensitivity=Number(input.value);saveControls();output.textContent=Math.round(controls.sensitivity*100)+'%';input.style.setProperty('--range',(controls.sensitivity-.5)*100+'%');};slider.append(text,output,input);panel.append(slider);
      const note=document.createElement('p');note.className='control-note';note.textContent='Проведи пальцем по герою, чтобы повернуть модель.';panel.append(note);
    }
    const hint=document.createElement('p');hint.textContent='Изменения сразу видны в таверне и сохраняются для игры.';hint.className='cinema-settings-hint';panel.append(hint,button('Сбросить настройки',()=>{Object.assign(s,defaults);controls={sensitivity:1,inertia:true};saveControls();gameDebug.save();gameDebug.render();persist();settings(category);},'settings'));root.append(panel);const status=document.createElement('p');status.id='cinema-status';status.setAttribute('role','status');root.append(status);
  }
  function setHero(actor,anchor){if(active)editor={actor,anchor};}
  function init(){const root=document.createElement('section');root.id='cinematic-menu';document.body.append(root);$('modal').addEventListener('close',()=>{if(active&&!document.querySelector('dialog[open]')&&(route==='heroes'||route==='worlds'))home();});applyPreferences();if(!localStorage.getItem('beyond-menu-preferences')){Object.assign(gameDebug.state.settings,defaults);persist(false);}open();const settingsButton=button('Настройки',()=>{fromGame=true;active=true;document.body.classList.add('cinematic-active');settings();requestAnimationFrame(()=>window.voxel?.resize());},'settings');settingsButton.id='game-settings-open';$('hero-view').append(settingsButton);}
  window.CinematicMenu={init,open,home,play,closeScreen,setHero,settings,applyPreferences,get controls(){return controls;},get active(){return active;},get editor(){return editor;},get route(){return route;},clearHero:()=>{editor=null;}};
})();
